"""Из слов заказчика — ПЛАН, и сразу же через валидатор-2.

ЗАЧЕМ ЭТОТ МОДУЛЬ СУЩЕСТВУЕТ

Владелец описал продукт дословно: «Бот помогает собирать пайплайн на основе
готового креатива и с нуля». В репозитории было две половины и ни одного
моста между ними: `studio/pipeline.py` ПРИНИМАЕТ пайплайн и судит его семью
классами отказа, `studio/mcp/creative.py` разбирает поданный креатив — а
собрать план из брифа не умел никто.

ИЗМЕРЕНО 2026-09-02 до этого модуля (`scripts/planner_baseline.py`, снимок в
`studio/fixtures/planner_baseline_2026-09-02.txt`), восемь настоящих брифов:

    шагов плана ожидается 10, собрано репозиторием 0

и, что важнее, ЕДИНСТВЕННЫЙ существовавший мост «слова задачи -> база»
(`studio/factindex.py`, поданный брифом целиком) для выбора моделей не годен:

    «оживить фото клиента, 10 секунд, он говорит мою озвучку»
        -> sdxl-turbo, krea-2, stable-diffusion-3-medium, sulphur-2-base ...
           восемь имён, из них ни одно не делает липсинк; это картиночные модели
    «нужен пайплайн, который по видеопотоку управляет промышленным
     манипулятором на складе»
        -> исход `pass`, факт про `indextts-2`
    «заменить персонажа в готовом ролике, сохранив цветокор и освещение»
        -> НОЛЬ находок, хотя в базе лежит `wan-animate-replace` дословно об
           этом; бриф по-русски, база по-английски

То есть прибор отвечал ВСЕГДА и отвечал не тем. Планировщик, построенный на
такой подборке, выдал бы уверенный план из картиночных моделей — и это ровно
тот дефект, ради которого в этом доме заведено правило И5.

КАК ЗДЕСЬ ВЫБИРАЕТСЯ КАНДИДАТ, И ПОЧЕМУ НЕ ПОРОГОМ

Порог у поиска крутить бесполезно: `studio/factaxis.py` уже ИЗМЕРИЛ, что веса
верных и ложных подборов перемешаны. Поэтому кандидат отбирается не весом, а
ЯКОРЕМ: у каждой операции студии выписаны термины, которыми эту операцию
называет сама база (`lipsync`, `img2vid`, `text-to-speech`, ...), и моделью-
кандидатом считается та, о которой есть утверждение, СОДЕРЖАЩЕЕ якорный
термин. Второго поиска для этого не заводится (Е1): якоря подаются запросом в
тот же `studio.factindex.FactIndex`, и совпавшие слова печатаются рядом с
кандидатом — их видно, а не подразумевается.

Цена названа вслух (И6): якорь ловит только то, что база написала словами
операции. Модель, которая делает липсинк, но у которой в базе не стоит ни
одного из якорных слов, в кандидаты не попадёт. Это ПРОПУСК, и он честнее
подбора по весу, потому что пропуск виден как «кандидатов нет», а ложный
подбор виден как уверенный план.

ЧТО ЗДЕСЬ НЕ ДЕЛАЕТСЯ НИКОГДА

Не подставляется модель «по умолчанию». Шаг без кандидата остаётся ПУСТЫМ, а
исход всего плана — третий. Пустой шаг честнее выдуманного: выдуманный уходит
в работу и возвращается через неделю.

Не выдумывается цена. Цена берётся у `studio/pipeline.comparable_prices`, то
есть у разборщика `studio/pricing.py` (Е1), и если сравнимой строки нет — в
плане стоит «цена не записана», а не число.

Не выдумывается бюджет. Заказчик не назвал потолок — потолка нет, и цена не
решает в отборе ничего.

ЦЕНА И БЮДЖЕТ: ДВА ДЕФЕКТА, НАЙДЕННЫЕ ЧТЕНИЕМ ВЫДАЧИ 2026-09-02 (П3)

Первая версия модуля печатала цену и не пользовалась ею. Наблюдено дословно
на «нужен липсинк на готовое видео, бюджет 0.5 доллара»:

    шаг липсинк: wav2lip — применимость измерена: 2 строк(и)
        цена: цена не записана
        ещё кандидаты (15 всего): latentsync (применимость измерена: 1 строк(и))

Три отдельных дефекта в одной строке:

    1. бюджет, названный в брифе СЛОВАМИ, не разбирался вовсе;
    2. цена не участвовала в порядке кандидатов даже когда бюджет приходил
       параметром;
    3. цена считалась ПО ЯКОРНЫМ строкам модели, а не по всем. У `latentsync`
       якорных строк три и цены среди них нет, а всего строк десять и первая
       из них — `price = "$0.2 for videos up to 40 seconds..."`. То есть цена
       была невидима планировщику целиком.

Починено так: потолок разбирается из фразы заказчика (`budget_from`, три
исхода и негативный контроль), положение кандидата относительно потолка —
одно из ЧЕТЫРЁХ (`PRICE_ORDER`), и оно становится СТАРШИМ ключом отбора, но
только когда потолок назван. Четыре, а не три, потому что «цена записана, но
с бюджетом несравнима» и «цены нет ни строки» — разные состояния, и слияние
их и было вторым дефектом: у первого читатель видит число и решает сам.

ОСЬ НЕВОЗМОЖНОГО: ЧЕТЫРЕ ПРИЧИНЫ, ОДНО ПОЛЕ КЛЮЧА

«Вход шага запрещён», «кадр не принимается», «модель уже отключена» и
«нужного вида не отдаёт» — проявления одного вопроса: этим воспользоваться
нельзя. Три похожих правила в
трёх местах разъезжаются (Е1), поэтому в ключе отбора у них ОДНО поле
(`blocked_rank`, максимум из шкал), а в выдаче — три разных объяснения, потому
что чинить их надо по-разному.

СИММЕТРИЯ ВХОДА И ВЫХОДА. Долго проверялось только то, что модель ПРИНИМАЕТ.
Шаг «озвучка» объявляет `produces: аудио` и получал `pixverse-lipsync`, которая
отдаёт видео: перечень голосов в её схеме есть, потому что TTS у неё
внутренний, и якорь сработал на этой внутренней детали. Теперь `produces` шага
сверяется с записанным выходом модели (`OUTPUT_KINDS`, `output_stance`), и
«выход не записан» — третий исход, а не согласие: выход записан у 44 моделей
из 543.

Конец службы разбирает `studio/lifecycle.py` целиком, вместе со своим
негативным контролем. Различие исходов здесь решающее: «уже отключена» —
отказ, «отключат 2026-09-24» — ПРЕДУПРЕЖДЕНИЕ. Модель со сроком впереди ещё
отвечает, и выбросить её значит выбросить рабочую.

ЗАПРЕТ НА ВХОД — СТЕНА, А НЕ ПЛОХАЯ НОВОСТЬ О КАЧЕСТВЕ

Шестой заход. На шаге липсинка выбирался `seedance-2.0`, и ОБОСНОВАН выбор был
строкой `face_reference_restriction = "real human faces cannot be uploaded as
reference images or videos"` — то есть запретом на тот самый вход, который у
шага есть. Довод сработал доводом, потому что якорь поймал слово `face`, а ЗНАК
утверждения не смотрел никто.

Это не то же, что записанный выше предел порядка («поднимаем кандидата с плохой
новостью выше того, о ком молчат»). Там `failure_mode` — измеренная
применимость, плохая новость о КАЧЕСТВЕ, и она законный довод против. Здесь
запрет на ВХОД: не довод, а стена.

Три положения (`BAN_ORDER`), и главное из них третье: «о запрете не сказано» НЕ
равно «разрешено». Список форм запрета выведен из ЗНАЧЕНИЙ живой базы, а не из
звучания имён, и каждая форма — целая фраза с обеими половинами: что за вход и
что с ним нельзя. Ловля по одному слову зажгла бы десять строк, запретом не
являющихся (см. `BAN_FORMS`).

Мост между «вход шага объявлен артефактами» и «запрет написан про лицо» —
`Operation.face_input`: видео на входе липсинка есть по определению говорящая
голова, хотя артефакт называется просто «видео».

ПОДАННЫЙ КРЕАТИВ ДОЕЗЖАЕТ ДО ОТБОРА, А НЕ ТОЛЬКО ДО РАСШИРЕНИЯ

Пятый заход, и он закрывает вторую половину цели владельца: «на основе готового
креатива». `creative` принимался и читался ТОЛЬКО расширением — упоминаний
1536x2752 в выдаче по этому самому файлу было НОЛЬ, — и планировщик мог
предложить модель, которая такого кадра не принимает: на 1536x2752 из 44
записанных пределов не влезают 30.

Кадр меряет `studio/mcp/creative.py` (тот же прибор, что отвечает на
`analyse_creative`), строку предела разбирает и сравнивает
`studio/resolution.py`. Своего измерителя и своего разборщика здесь нет (Е1).

Положений по кадру ЧЕТЫРЕ, той же формы, что и по цене, и по той же причине:
«предел не записан» — не «принимает». На живой базе строка о разрешении есть у
41 модели из 505, и свернуть незнание в согласие значило бы молча объявить
подходящими 92% кандидатов.

Кадр стоит в ключе ПЕРЕД ценой: модель, которая кадра не принимает, не
запустится вовсе, а модель дороже потолка запустится и сделает работу, просто
дорого. Невозможное старше нежелательного.

ПЕРЕВОД «ЗА ЧТО»: ЧТО ПЕРЕВОДИТСЯ И ЧТО НЕ ПЕРЕВОДИТСЯ НИКОГДА

Четвёртый заход. Цена `$0.6 за минуту` при потолке `$0.10 за секунду`
объявлялась НЕСРАВНИМОЙ — при том что это $0.01 за секунду, десятикратный
запас. Прибор говорил «сравнить не с чем» там, где перевод точный.

Запретов на самом деле два, и они были слиты в один. Кредиты в доллары не
переводятся, потому что курс — решение вендора и он нигде не записан. Секунда
в минуту переводится, потому что шестьдесят — не чьё-то решение, а определение
единицы. Теперь единица (`unit`) не переводится НИКОГДА, а «за что» (`per`) —
только внутри одного измерения и только по множителю-определению
(`PER_CONVERSION`, одна пара, выведенная из `SECONDS_IN_MINUTE`).

Переведённое число НАЗЫВАЕТСЯ переведённым (`CONVERTED_MARK`), и исходная
строка стоит рядом: «$0.6 за минуту = $0.01 за секунду». Число, посчитанное
нами, обязано быть отличимо от числа, записанного вендором, — в самой выдаче,
а не в голове читателя.

ЧТО СТАЛО С ПРОВЕРЕННЫМИ, КОГДА ЦЕНА ПЕРЕСТАВИЛА ПОРЯДОК

Третий заход того же разбора. Потолок «$0.05 за секунду» поднял наверх три
модели с НЕИЗМЕРЕННОЙ применимостью, а четыре проверенных уехали вниз из
двадцати восьми и в выдачу не попали вовсе. Порядок был верен — потолок назвал
человек, — и каждая напечатанная строка была правдой; неверен был ЗАГОЛОВОК:
читатель видел три недоказанные модели и не получал ни одного признака, что
доказанная существует.

Поэтому у шага есть ОДНА строка (`rival_line`), и положений в ней три, а не
два: выбранный сам проверен — строки нет; выбранный не проверен, а проверенный
есть — он назван вместе с тем, чем проиграл; проверенных нет ни одного — сказано
ДРУГИМИ словами. Одно молчание на два разных положения дел и было бы тем самым
дефектом.

ПОЧЕМУ ВЫБРАН ЭТОТ, А НЕ СОСЕД

Рядом с каждым шагом печатается `why_not`: ПЕРВОЕ поле ключа отбора, которым
выбранный разошёлся со следующим за ним. Считается из того же кортежа, по
которому произошёл отбор, а не пишется словами рядом — написанное рядом
объяснение разъезжается с отбором молча (Е2).

Не заводится второго валидатора. План собирается в `pipeline.Pipeline` и
уходит в `pipeline.pipeline_report` как есть; исход плана здесь НЕ
пересчитывается, а берётся у него.

ТРИ ИСХОДА (Р1), И ГЛАВНЫЙ ИЗ НИХ ТРЕТИЙ

    годно      — план собран, и валидатор-2 его не опроверг;
    не годно   — план собран, и валидатор назвал класс отказа. Возвращается И
                 план, И класс: «не годно» без плана нечего чинить;
    не смогли  — из брифа не выводится ни один шаг (`шаги_не_выведены`), либо
                 у шага нет ни одного кандидата с доказательством
                 (`шаг_без_кандидатов`), либо валидатор сам сказал третье
                 (`план_не_подтверждён`).

ДОКАЗАТЕЛЬСТВО СТОИТ РЯДОМ С КАНДИДАТОМ, А НЕ В КОММЕНТАРИИ

У каждого кандидата печатается, ЧЕМ он выбран: атрибут, значение, ступень
источника (`tier`), дата (`stated_on`) и РОД свидетельства по второй оси
(`studio/factaxis.py`: schema / claim / measurement / witness). Род решает
формулировку: если о модели есть только вендорская схема и проза, у кандидата
стоит `NOT_MEASURED_MARK` — «применимость не измерена», и стоит она в выдаче,
в поле, которое нельзя не прочитать.
"""

