@dataclass(frozen=True)
class Budget:
    """Потолок, названный заказчиком, и три исхода его разбора (Р1).

    `amount is None` — это состояние, а не число: либо о бюджете не было речи,
    либо речь была и разобрать не удалось. Оба несут исход «не смогли» и
    РАЗНЫЕ ноты, потому что человеку в этих случаях отвечают разное — искать
    деньги или переспросить, сколько и за что.
    """

    amount: float | None
    unit: str
    per: tuple[str, ...]
    outcome: str
    note: str

    @property
    def known(self) -> bool:
        return self.amount is not None


@dataclass(frozen=True)
class Evidence:
    """Одна строка доказательства: ЧЕМ кандидат выбран.

    Четыре поля из требования владельца стоят здесь буквально — значение,
    ступень источника, дата и род свидетельства, — и пятое, `matched`, говорит,
    каким якорным словом эта строка вообще попала в подборку.
    """

    attribute: str
    value: str
    tier: str
    stated_on: str
    kind: str
    axis: str
    source_url: str
    matched: tuple[str, ...]
    #: Когда это сказал САМ источник, если он это сообщает (`ГГГГ-ММ`, РАСЧЁТ по
    #: arxiv-идентификатору). Печатается рядом с `stated_on`, когда они
    #: расходятся: `stated_on` на 2560 строках из 4400 — день НАШЕГО чтения, и
    #: у 173 строк со статьями он опережает публикацию, доходя до 2 лет
    #: 9 месяцев. Утверждение трёхлетней давности выглядело ровно как вчерашнее.
    published_on: str = ""
    #: Какой вход шага эта строка ЗАПРЕЩАЕТ, если запрещает. Непустое поле
    #: означает, что строку нельзя печатать под словами «чем выбран»: одно и
    #: то же утверждение не может быть одновременно основанием выбора и
    #: причиной отказа.
    forbids: str = ""
    #: Знак, ОБЪЯВЛЕННЫЙ записавшим (`Fact.contra`): `False` — строка о
    #: провале, которая провал ОПРОВЕРГАЕТ («ОПРОВЕРГНУТО: minimax-h3
    #: моргает»). Без этого поля словарь доказательства терял знак, и
    #: `худшая_новость` по имени `failure_mode` зачитывала опровержение
    #: заказчику как «измеренный провал» (пункт 11, 2026-10-15).
    contra: bool | None = None


@dataclass(frozen=True)
class Candidate:
    """Одна модель, предложенная на шаг, и весь её счёт доказательств."""

    model: str
    evidence: tuple[Evidence, ...]
    applicability: int
    capability: int
    unresolved: int
    price: str
    #: Сколько строк применимости — ПЛОХИЕ НОВОСТИ (`factaxis.CONTRA_ATTRIBUTES`).
    #: Заведено 2026-09-05: без знака ключ отбора считал строки штуками, и две
    #: плохие обгоняли одну хорошую. Знак берётся у `studio/factaxis.py` и
    #: вторым списком здесь не переписывается (Е1).
    against: int = 0
    #: Та же цена РАЗОБРАННОЙ. Держится рядом со строкой, а не выводится из
    #: неё: строка — для человека, объект — для суммы пайплайна.
    price_value: "pricing.Price | None" = None
    #: Сколько утверждений о модели вообще зацепилось за якоря операции.
    #: Печатается и участвует в порядке: одна строка и одиннадцать строк — это
    #: разная степень, с какой база связывает модель с этой работой.
    anchored: int = 0
    #: Несёт ли САМО ИМЯ модели якорный термин (`wan-animate-replace`).
    #: Свидетельство слабое и потому стоит последним ключом порядка — но при
    #: прочих равных оно единственное непроизвольное: до него порядок решался
    #: алфавитом, и на замене персонажа алфавит поднимал `sdxl-lightning`
    #: (картиночная модель, зацепившаяся словом `replace` из куска кода) выше
    #: `wan-animate-replace`, у которой в базе записано «replaces the character
    #: in a reference video, keeping the scene». НАЙДЕНО ЧТЕНИЕМ ВЫДАЧИ,
    #: 2026-09-02 (П3).
    named: bool = False
    #: Одно из четырёх положений относительно названного потолка
    #: (`PRICE_ORDER`), и нота, которой оно объясняется. Пустая строка — это
    #: «положение не считали», и она отличима от `PRICE_ABSENT`: первое значит,
    #: что мерить не начинали, второе — что мерили и цены нет.
    price_state: str = ""
    price_note: str = ""
    #: Одно из четырёх положений относительно ПОДАННОГО КАДРА (`FIT_ORDER`) и
    #: нота к нему. Пустая строка — «кадр не подан», и она отличима от
    #: `FIT_ABSENT`: первое значит, что не с чем сравнивать, второе — что
    #: сравнивали и предел не записан.
    fit_state: str = ""
    fit_note: str = ""
    #: Одно из ПЯТИ положений по длительности (`duration.DUR_ORDER`) и нота.
    #: Пятое — «не спрашивали»: оно про бриф, а не про модель, и лечится
    #: вопросом заказчику, а не сбором.
    dur_state: str = dur.DUR_NOT_ASKED
    dur_note: str = ""
    #: Одно из трёх положений относительно ВХОДА ШАГА (`BAN_ORDER`) и нота.
    #: Пустая строка невозможна: вход у шага есть всегда, и молчание базы —
    #: это `BAN_UNKNOWN`, а не отсутствие ответа.
    ban_state: str = BAN_UNKNOWN
    ban_note: str = ""
    #: Одно из трёх положений по КОНЦУ СЛУЖБЫ (`LIFE_ORDER`) и нота к нему.
    life_state: str = LIFE_LIVE
    life_note: str = ""
    #: Одно из трёх положений по ВЫХОДУ (`OUT_ORDER`) и нота к нему. Та же ось
    #: невозможного, что запрет на вход и конец службы.
    out_state: str = OUT_UNKNOWN
    out_note: str = ""
    #: Модель делает ДРУГУЮ работу (`чужая_работа`), хоть и найдена под эту.
    foreign: bool = False
    #: Длиннее предела — стена (`False` у генерации клипами, см. `Operation.клипами`).
    dur_wall: bool = True
    #: Лицензия запрещает заявленное применение (тот же оракул, что у
    #: валидатора: `pipeline.probe_licence`). Стена, а не довод: модель,
    #: которую валидатор тут же отвергнет по лицензии, выбирать незачем.
    licence_blocked: bool = False
    licence_note: str = ""
    #: Сколько стоит ШАГ этим кандидатом на ЭТОМ брифе (длительность, кадр,
    #: звук) — по таблице ставок вендора (`pricing.rates`), с тарифами рядом.
    #: None — посчитать нельзя: цены нет, она в кредитах или не на что умножать.
    cost: "Стоимость | None" = None
    #: Предел ОДНОГО прогона модели в секундах, как он записан (`max_seconds` и
    #: родня). None — не записан. Нужен для счёта шотов: ролик 40 с у модели с
    #: пределом 10 с — четыре шота и четыре ключевых кадра (2026-10-15).
    run_s: float | None = None
    #: Чем модель рискует для ЭТОГО заказа помимо качества: территориальные
    #: исключения лицензии, порог выручки, открытые веса против API (G8).
    licence_risk: str = ""
    #: Поколение: модель вытеснена более новой (своей семьи или записью базы).
    #: Пусто — признаков нет; иначе — чем вытеснена (G4).
    superseded: str = ""
    #: Модель из сообщества (воркфлоу, LoRA, мёрж с портала) — не продукт
    #: вендора; в кандидаты идёт последней, если заказчик сам не просил (G4).
    community: bool = False
    #: Провалы, записанные при УСЛОВИЯХ, которых в брифе нет (текст в кадре,
    #: руки, несколько людей...): в счёт не идут, печатаются оговоркой (G6).
    outside_brief: tuple[str, ...] = ()
    #: Цена в порядке НЕ участвует: никто с записанной ценой в потолок не влез.
    price_rank_off: bool = False
    #: Лицензия модели ИСКЛЮЧАЕТ территории, а юрисдикция заказчика в брифе НЕ
    #: названа (2026-10-15). Не стена — заказчик может работать там, где
    #: лицензия действует, — но и не умолчание: см. `by_evidence`.
    territory_unasked: bool = False
    #: Модель по ЗАПИСИ не дотягивает до кадра, заказанного в брифе: её тариф
    #: считается в меньшем разрешении или предел кадра записан ниже (2026-10-15).
    #: Молчание сюда НЕ относится — «не записано» не значит «ниже».
    below_frame: bool = False
    #: Род работы внутри шага, решённый ДО общего ключа (шаг со звуком:
    #: видеомодель 0, аватар-продукт 1). Полоса бюджета (`полоса`) его не
    #: пересекает: дешёвый аватар не заменяет видеомодель ради денег.
    kind_rank: int = 0
    #: Поле ключа жёстких требований (`HARD_KEY_FIELD`): пусто — требований нет.
    hard_rank: tuple = ()
    #: Чем требования заказчика подтверждены или нет — словами (веса, VRAM, кадр).
    hard_note: str = ""
    #: Реестр эндпоинтов (`studio/endpoints.py`) НЕ установил, какую работу
    #: модель делает: свидетельства нет ни в идентификаторе, ни в каталоге, ни
    #: в схеме. Кандидат найден старыми каналами (якорь, профиль) и стоит ПОСЛЕ
    #: тех, чья работа установлена (2026-10-15, пятый круг).
    unclassified: bool = False
    #: Заказано САМОЕ ДЕШЁВОЕ: кандидат без полной цены встаёт после всех с
    #: ценой — «самое дешёвое» нельзя доказать моделью, чья цена неизвестна.
    unpriced_last: bool = False
    #: Чем реестр подтвердил работу кандидата (канал и свидетельство) — словами.
    registry_note: str = ""
    #: Цель «качество»: родной кадр ПО ЗАПИСИ ниже заказанного — сколько он
    #: (короткая сторона; 1 — ниже, но сколько — не записано) и почему. Такой
    #: кандидат исключается, только если хоть кто-то отдаёт кадр родным
    #: (`родной_кадр_или_ближайший`, шестой круг).
    native_below_px: int = 0
    native_below_why: str = ""

    @property
    def measured(self) -> bool:
        """Есть ли хоть одна строка применимости. Это и есть развилка пометки."""
        return self.applicability > 0

    @property
    def in_favour(self) -> int:
        """Строки применимости, которые НЕ плохие новости.

        Отрицательное никогда не вычитается из положительного: одна хорошая
        строка и одна плохая — это не «ноль», это спор, и спор виден числами
        порознь (`applicability`, `against`, `in_favour`), а не одной разностью.
        """
        return max(0, self.applicability - self.against)

    @property
    def mark(self) -> str:
        """Пометка для человека: сколько строк применимости и КАКИЕ.

        ЗНАК ДОБАВЛЕН 2026-09-05 по независимому аудиту. Пометка печатала
        «применимость измерена: 4 строк(и)» там, где три строки из четырёх
        были о том, где модель ломается, — и валидатор тут же отвергал шаг
        именно по ним. Это единственная строка, по которой читатель судит о
        модели, и она давала положительный знак от отрицательного замера.
        Тот же дефект, что утром того же дня сделал первое «годно» ложным,
        только не в вердикте, а в витрине.
        """
        if not self.measured:
            return NOT_MEASURED_MARK
        хвост = (
            f", из них {self.against} о том, где ломается"
            if self.against
            else ", плохих новостей нет"
        )
        return f"применимость измерена: {self.applicability} строк(и){хвост}"


def _norm(text: str) -> str:
    return " ".join(str(text or "").split()).lower()


#: Латинская подсказка ищется ПО ГРАНИЦЕ СЛОВА, русская — подстрокой.
#:
#: НАЙДЕНО седьмой приёмкой 2026-09-07: английские подсказки этого дня давали
#: 9 ложных срабатываний на брендах и топонимах —
#:
#:     «ролик про отель в Dubai, видео снято»     -> шаг ДУБЛЯЖА (`dub`)
#:     «промо для клуба Dubstep Nation»           -> то же
#:     «промо студии SFX Masters»                 -> шаг ФОНОВОГО ЗВУКА
#:
#: Разница языков здесь не произвол: русское слово склоняется, и подстрока —
#: единственный дешёвый способ поймать «озвучку/озвучки/озвучке». Английское
#: не склоняется, и подстрока в нём ловит только чужие слова.
_ЛАТИНСКАЯ = re.compile(r"^[a-z0-9 '.-]+$")

#: `_ИМЯ_СОБСТВЕННОЕ` УДАЛЕНО 2026-09-07 по девятой приёмке. Регулярка не
#: вызывалась ниоткуда (grep по репозиторию: одно совпадение — само
#: определение), потому что её сменила `_ЦЕПОЧКА_ЗАГЛАВНЫХ`: имена собственные
#: затираются цепочками, а не по одному слову. Мутанта на мёртвую ручку не
#: бывает, а следующий читатель принял бы её за действующее правило — и правил
#: бы её вместо той, что работает. Сказано здесь, чтобы удаление не выглядело
#: потерей.

#: Латинские слова брифа — чтобы посчитать, СКОЛЬКО из них с заглавной.
_ЛАТИНСКОЕ_СЛОВО = re.compile(r"\b[A-Za-z][A-Za-z0-9]*\b")

#: Доля заглавных, выше которой регистр перестаёт что-либо значить.
#: КОНСТАНТА-РЕШЕНИЕ, ВЫБРАНО 0.6 по восьмой приёмке 2026-09-07: заказчик
#: пишет Title Case и КАПСОМ, и тогда заглавная буква — не признак имени, а
#: оформление всего текста.
ЗАГЛАВНЫХ_СЛИШКОМ = 0.6


def _регистр_что_то_значит(brief: str) -> bool:
    """Несёт ли заглавная буква в этом брифе признак имени собственного.

    НАЙДЕНО восьмой приёмкой 2026-09-07, и это регресс починки того же дня.
    Маска имён собственных вычёркивала ЛЮБОЕ латинское слово с заглавной — и
    канонический заказ студии переставал разбираться:

        «нужен Lip Sync на готовое видео»            -> совпало 0
        «BRIEF: TALKING HEAD AD, 30 SECONDS»         -> совпало 0
        «Make Me A Talking Avatar Ad, 15 Seconds»    -> совпало 0

    ИЗМЕРЕНО на собственном наборе коммита: как есть 11 из 11, Title Case 6 из
    11, КАПС 6 из 11. То есть починка брендов сломала ровно то, что чинила
    правка абзацем выше.

    Разница наблюдаема и не требует словаря: заглавная буква говорит об имени
    ТОЛЬКО в тексте, написанном обычным регистром. Там, где заглавных больше
    половины, она не говорит ничего, и вычёркивать по ней нельзя.
    """
    текст = str(brief or "")
    # В КИРИЛЛИЧЕСКОМ БРИФЕ ЛАТИНСКОЕ СЛОВО С ЗАГЛАВНОЙ — ПОЧТИ ВСЕГДА ИМЯ, и
    # доля тут ни при чём: «промо для Talking Tom, видео готово» — два
    # латинских слова, оба с заглавной, доля 1.0, а имя это, а не оформление.
    # Найдено собственным прогоном сразу за починкой: доля считалась по
    # латинским словам, и в русском брифе она всегда получалась единицей.
    if _есть_кириллица(текст):
        return True
    слова = _ЛАТИНСКОЕ_СЛОВО.findall(текст)
    if len(слова) < 2:
        return True
    заглавных = sum(1 for с in слова if с[:1].isupper())
    return заглавных / len(слова) < ЗАГЛАВНЫХ_СЛИШКОМ


#: Цепочка слов с заглавной подряд: «Talking Tom», «Avatar Maker», «Lip Sync».
#:
#: `:` И `;` ВЕРНУЛИСЬ В LOOKBEHIND 2026-09-07 по десятой приёмке, и это
#: отмена вчерашнего решения с числами обеих сторон. Девятая приёмка измерила
#: снятие на СВОЁМ наборе («не теряет ни одного заказа»), и это было правдой
#: ровно потому, что ни в одной фикстуре репозитория нет брифа вида «Ярлык:
#: Заглавная». Десятая собрала такой набор: 12 потерянных заказов против 3
#: убранных ложных срабатываний —
#:
#:     «Задача: Lipsync нашего видео»   -> совпало 0
#:     «Job: Dub our video into German» -> совпало 0
#:     «Brief: Voiceover for the ad»    -> совпало 0
#:
#: Ярлык — самый обычный способ начать бриф, и слово после него начинает фразу.
_ЦЕПОЧКА_ЗАГЛАВНЫХ = re.compile(
    r"(?<![.!?:;]\s)(?<!^)(?<!\n)\b[A-Z][A-Za-z0-9]*(?:\s+[A-Z][A-Za-z0-9]*)*", re.M
)

#: ЗА ЯРЛЫКОМ слово с заглавной — начало фразы, если оно ОДНО, и имя
#: собственное, если их два и больше: «Задача: Lipsync» остаётся заказом,
#: «Client: Talking Tom» — вывеской. Так закрыты те три ложных срабатывания,
#: ради которых двоеточие вчера снимали целиком.
_ЦЕПОЧКА_ЗА_ЯРЛЫКОМ = re.compile(r"(?<=[:;]\s)\b[A-Z][A-Za-z0-9]*(?:\s+[A-Z][A-Za-z0-9]*)+", re.M)


#: Слова, которыми кончается НАЗВАНИЕ КОМПАНИИ. Закрытый список: цепочка
#: заглавных, кончающаяся таким словом, — вывеска, чем бы она ни начиналась.
#:
#: НАЙДЕНО девятой приёмкой 2026-09-07: спасение цепочки составной подсказкой
#: открыло её целиком — «our client is Talking Head Studios, make a poster» и
#: «клиент Voice Over Inc, нужна визитка» заказывали липсинк и озвучку. Бренд,
#: совпадающий с нашим термином, — тоже бренд, и различает их форма компании.
ФОРМЫ_КОМПАНИЙ: frozenset[str] = frozenset(
    {
        "inc",
        "ltd",
        "llc",
        "gmbh",
        "studio",
        "studios",
        "records",
        "media",
        "agency",
        "group",
        "films",
        "productions",
        "lab",
        "labs",
        "co",
        "corp",
    }
)


#: Слова, после которых идёт НАЗВАНИЕ, а не заказ: «промо СТУДИИ sfx masters»,
#: «реклама ПРИЛОЖЕНИЯ talking tom». Признак работает и на строчных, где
#: регистр не говорит ничего.
#:
#: НАЙДЕНО восьмой приёмкой 2026-09-07 и оставалось открытым до десятой: три
#: вывески из шести, написанные строчными, заказывали работу. Регистр —
#: единственный признак, которым закрыты заглавные, и в строчном тексте его
#: нет; зато есть родовое слово перед названием, и его заказчик пишет всегда.
ВЫВЕСКА_ВПЕРЕДИ: tuple[str, ...] = (
    "студи",
    "приложени",
    "сервис",
    "компани",
    "фирм",
    "бренд",
    "марк",
    "сет",
    "агентств",
    "магазин",
    "отел",
    "клуб",
    "заведени",
    "проект",
    # АНГЛИЙСКИЕ РОДОВЫЕ СЛОВА (2026-09-08). ИЗМЕРЕНО одиннадцатой приёмкой на
    # её собственном наборе: из 8 английских вывесок молчало 0 — список состоял
    # из одних русских корней, и «ad for the app talking tom» заказывало
    # липсинк. Английский почти не склоняется, поэтому основы короче.
    "app",
    "studio",
    "service",
    "brand",
    "compan",
    "agenc",
    "shop",
    "hotel",
    "club",
    "chain",
    "startup",
    "label",
)

#: РОДОВОЕ СЛОВО ИДЁТ И ПОСЛЕ НАЗВАНИЯ: «sfx masters studio», «avatar maker
#: app», «voice over inc». По-английски это обычный порядок слов, и первая
#: редакция, смотревшая только назад, ловила из них ноль.
#:
#: ГРАНИЦА ЗАПИСАНА, А НЕ ЗАКРЫТА НАУГАД (И6). Обе редакции смотрят СОСЕДНЕЕ
#: слово, поэтому вывеска, у которой родовое слово стоит через слово и дальше
#: («промо для новой студии звукозаписи sfx masters», «промо sfx masters, это
#: студия звука»), по-прежнему заказывает работу. ИЗМЕРЕНО на наборе приёмки:
#: таких 2 из 12. Наблюдаемого признака дешевле у нас нет, а окно назад мы уже
#: пробовали — оно теряет настоящие заказы («реклама сети кофеен, нужен
#: talking head»).
#: Слова, на которых поиск родового слова ВПЕРЁД обрывается. Название состоит
#: из слов названия, а не из предлогов: «voiceover FOR OUR app» — это заказ
#: озвучки для приложения, а «avatar maker app» — вывеска. Различает их ровно
#: то, что стоит между подсказкой и родовым словом.
СЛУЖЕБНЫЕ_ЗА_ПОДСКАЗКОЙ: frozenset[str] = frozenset(
    {"for", "our", "the", "a", "an", "in", "to", "and", "of", "my", "we", "with", "on", "is"}
)

#: Сколько слов названия допускается между подсказкой и родовым словом.
#: ВЫБРАНО (не измерено): длиннее трёх слов названия в брифах не встречалось.
ХВОСТ_НАЗВАНИЯ = 3


def _вывеска_позади(низ: str, конец: int) -> bool:
    """Идёт ли ПОСЛЕ подсказки родовое слово, а между ними — только название.

    Обрыв на служебном слове и на знаке препинания обязателен: без него
    «voiceover for our app» читалось бы вывеской, а это обычный заказ.
    """
    for слово in низ[конец:].split()[:ХВОСТ_НАЗВАНИЯ]:
        чистое = слово.strip(".,;:!?")
        if not чистое or чистое in СЛУЖЕБНЫЕ_ЗА_ПОДСКАЗКОЙ:
            return False
        # ФОРМА КОМПАНИИ — ТО ЖЕ РОДОВОЕ СЛОВО, и список для неё уже есть (Е1):
        # «voice over inc» отличается от «voice over studio» только словом.
        if чистое in ФОРМЫ_КОМПАНИЙ or any(чистое.startswith(с) for с in ВЫВЕСКА_ВПЕРЕДИ):
            return True
        if слово != чистое:
            return False
    return False


def _вывеска_впереди(низ: str, место: int) -> bool:
    """Стоит ли НЕПОСРЕДСТВЕННО перед подсказкой родовое слово вывески.

    Наблюдаемый признак вместо словаря брендов: брендов бесконечно много, а
    родовых слов конечное число, и заказчик ставит их почти всегда — иначе
    читатель не поймёт, о чьём названии речь.

    ИМЕННО СОСЕДНЕЕ СЛОВО, А НЕ ОКНО. Первая редакция смотрела 24 символа
    назад и своим же прогоном поймана на «реклама СЕТИ кофеен, нужен talking
    head»: родовое слово там относится к кофейням, а не к подсказке, и заказ
    терялся. Название идёт сразу за родовым словом — на том и стоим.
    """
    слова = низ[:место].split()
    return bool(слова) and any(слова[-1].startswith(с) for с in ВЫВЕСКА_ВПЕРЕДИ)


def _вывеска(низ: str, м: "re.Match[str]") -> bool:
    """Родовое слово с ЛЮБОЙ стороны подсказки. Одно место на оба порядка слов."""
    return _вывеска_впереди(низ, м.start()) or _вывеска_позади(низ, м.end())


def _составные_подсказки() -> frozenset[str]:
    """Латинские подсказки ИЗ БОЛЕЕ ЧЕМ ОДНОГО СЛОВА. Считаются из словаря
    операций, а не переписываются рядом (Е1)."""
    return frozenset(
        c.rstrip("*")
        for op in OPERATIONS
        for c in op.cues
        if " " in c.strip() and _ЛАТИНСКАЯ.match(c.rstrip("*"))
    )


def _без_имён_собственных(brief: str) -> str:
    """Тот же бриф, где имена собственные заменены пробелами.

    Заменяются, а не выбрасываются: места слов не должны съезжать — по ним
    ищутся многословные подсказки («lip sync», «talking head»).

    ЧЕМ «Lip Sync» ОТЛИЧАЕТСЯ ОТ «Talking Tom» В РУССКОМ БРИФЕ. Регистром —
    ничем: оба латинские, оба с заглавных, оба посреди фразы. Найдено
    собственным прогоном 2026-09-07 сразу после починки: правило «в
    кириллическом брифе заглавная латиница — имя» теряло «нужен Lip Sync на
    готовое видео» — канонический заказ студии.
    Различает их СОСТАВНОСТЬ: наш термин заказчик пишет целиком («lip sync»,
    «talking head», «voice over»), а бренд цепляется за одно общее слово
    («Talking» в «Talking Tom», «Avatar» в «Avatar Maker»). Цепочка заглавных,
    в которой лежит СОСТАВНАЯ подсказка, — это наш термин, и её не трогают.
    """
    текст = str(brief or "")
    if not _регистр_что_то_значит(текст):
        return _norm(текст)
    составные = _составные_подсказки()

    def затереть(м: "re.Match[str]") -> str:
        низ = _norm(м.group(0))
        слова = низ.split()
        # ФОРМА КОМПАНИИ СИЛЬНЕЕ СОСТАВНОЙ ПОДСКАЗКИ. «Talking Head Studios» —
        # вывеска, хотя «talking head» внутри неё наш термин.
        if слова and слова[-1].strip(".,") in ФОРМЫ_КОМПАНИЙ:
            return " " * len(м.group(0))
        if any(c in низ for c in составные):
            return м.group(0)
        return " " * len(м.group(0))

    # ЦЕПОЧКА ЗА ЯРЛЫКОМ ЗАТИРАЕТСЯ ПЕРВОЙ, и порядок здесь не вкусовой: общая
    # цепочка успевает стереть ВТОРОЕ слово («Tom» в «Client: Talking Tom»),
    # после чего за ярлыком остаётся одно слово, и правило «два и больше» не
    # срабатывает. Поймано собственным прогоном сразу после написания.
    первый = _ЦЕПОЧКА_ЗА_ЯРЛЫКОМ.sub(затереть, текст)
    return _norm(_ЦЕПОЧКА_ЗАГЛАВНЫХ.sub(затереть, первый))


def _подсказка_есть(cue: str, низ: str, без_имён: str) -> bool:
    """Встречается ли подсказка так, чтобы это была ОПЕРАЦИЯ, а не чужое слово.

    Три исхода тут не нужны — вызывающему нужен признак, — но развилка вынесена
    отдельно (Т5): именно она мутирует, и мутировать её надо порознь от списка
    подсказок.
    """
    if not _ЛАТИНСКАЯ.match(cue.rstrip("*")):
        return cue in низ
    # ОБЕ ГРАНИЦЫ, А НЕ ОДНА. НАЙДЕНО восьмой приёмкой: граница стояла только
    # слева, и «ролик про отель в dubai» по-прежнему заказывал ДУБЛЯЖ по `dub`,
    # «промо студии sfx masters» — фоновый звук. Приставка объявляется
    # звёздочкой в самом списке подсказок: `localis*` ловит «localise» и
    # «localisation», `dub` — только целое слово.
    if cue.endswith("*"):
        м = re.search(rf"\b{re.escape(cue[:-1])}", без_имён)
        return м is not None and not _вывеска(без_имён, м)
    # АНГЛИЙСКОЕ СЛОВО ТОЖЕ ИЗМЕНЯЕТСЯ, просто иначе. НАЙДЕНО девятой приёмкой
    # 2026-09-07, и это худшая регрессия дня: жёсткая граница справа оставила
    # от английских подсказок только точную форму —
    #
    #     «we need voiceoverS»       -> совпало 0
    #     «we need dubbING into German» -> совпало 0
    #     «replace characterS in the scene» -> совпало 0
    #
    # ИЗМЕРЕНО машинным перебором форм (s/es/ed/ing по всем латинским
    # подсказкам): было 168 из 168, стало 16. Заказчику отвечали «назовите
    # работу словом `voiceover`» — его же словом в единственном числе.
    #
    # Хвост закрытый: `s`, `es`, `ed`, `ing` и удвоение последней согласной
    # («dub» -> «dubbed», «dubbing»). Больше ничего: именно закрытость хвоста
    # оставляет «Dubai» и «Dublin» за бортом («ai» и «lin» в список не входят),
    # ради чего граница справа и заводилась.
    хвост = rf"(?:{re.escape(cue[-1])}?(?:s|es|ed|ing))?"
    м = re.search(rf"\b{re.escape(cue)}{хвост}\b", без_имён)
    # РОДОВОЕ СЛОВО ВОЗЛЕ ПОДСКАЗКИ ЗНАЧИТ, ЧТО РЯДОМ НАЗВАНИЕ. Так закрыты
    # строчные вывески, где регистр не говорит ничего.
    return м is not None and not _вывеска(без_имён, м)


#: Слова, которыми заказчик ОТМЕНЯЕТ операцию: «озвучка НЕ нужна», «НИКАКОГО
#: TTS», «БЕЗ дубляжа», «не генерируйте видео».
ОТМЕНА_ОПЕРАЦИИ: frozenset[str] = frozenset(
    {"не", "нет", "никакого", "никакой", "никаких", "без", "no", "not", "don't", "dont"}
)

#: Обороты, которыми операцию отменяют ПОСЛЕ её имени. Не отдельные слова, а
#: пары, и это измерено дважды подряд:
#:
#:   «липсинк БЕЗ спешки»            — «без» относится к спешке, а не к липсинку;
#:   «сделай липсинк, НЕ ДОРОЖЕ 0.10» — «не» относится к ЦЕНЕ.
#:
#: Второй случай поймал собственный голден-сет через минуту после первой
#: починки: одинокое «не» после операции отменяло её на самом обычном брифе с
#: потолком. Отменяет только оборот НЕОБХОДИМОСТИ.
ОТМЕНА_ПОСЛЕ: tuple[str, ...] = (
    "не нужн",
    "не надо",
    "не требуетс",
    "не дела",
    "не хочу",
    "не хотим",
    "нет нужды",
    "not needed",
    "don't need",
    "dont need",
    "no need",
)

#: Сколько слов вокруг подсказки смотрится на отмену. ВЫБРАНО 2: отрицание
#: стоит вплотную («озвучка не нужна», «не генерируйте видео»), а на большем
#: окне отмена цеплялась бы к любому «не» в брифе.
ОКНО_ОТМЕНЫ = 2


def _операция_отменена(низ: str, cue: str) -> bool:
    """Заказчик ЗАПРЕТИЛ эту операцию словами.

    НАЙДЕНО продуктовой проверкой 2026-09-07 (третий заход): бриф «Не
    генерируйте видео, у нас своё. Только липсинк и ничего больше» получал
    план, где шаг генерации видео стоит вторым, а «Озвучка не нужна, звук у нас
    уже есть» — план с шагом озвучки первым. Продукт делал ровно то, что ему
    запретили одной фразой, и брал за это деньги.

    Отрицание ищется ВПЛОТНУЮ к подсказке, окном в два слова: «липсинк без
    спешки» — про спешку, а не про липсинк, и широкое окно снимало бы операцию
    с любого брифа, где рядом стоит «не».
    """
    if cue.startswith(CUE_REGEX) or cue.startswith(CUE_REGEX_INPUT):
        м = re.search(cue.split(":", 1)[1], низ)
        if м is None:
            return False
        cue = м.group(0)
    место = низ.find(cue.rstrip("*"))
    if место < 0:
        return False
    хвост_cue = cue.rstrip("*")
    # ХВОСТ БЕРЁТСЯ ОТ КОНЦА СЛОВА, А НЕ ОТ КОНЦА ПОДСКАЗКИ: подсказка `озвучк`
    # кончается внутри слова «озвучка», и окно начиналось с огрызка «а» —
    # оборот «не нужна» до сравнения не доходил (поймано своим же прогоном).
    конец = место + len(хвост_cue)
    while конец < len(низ) and низ[конец].isalpha():
        конец += 1
    до = низ[:место].split()[-ОКНО_ОТМЕНЫ:]
    после = " ".join(низ[конец:].split()[:ОКНО_ОТМЕНЫ])
    return any(с in ОТМЕНА_ОПЕРАЦИИ for с in до) or any(о in после for о in ОТМЕНА_ПОСЛЕ)


#: Подсказка-РЕГУЛЯРКА: `re:<выражение>` ищется в брифе как есть. Заведено
#: 2026-10-14: подстрока `фото` жила внутри «фотореалистичные», а целое слово
#: подстрокой не выразить.
CUE_REGEX = "re:"

#: Подсказка-регулярка, которая называет ПРИНЕСЁННЫЙ вход и потому НЕ
#: считается внутри клаузы с глаголом генерации: в «сгенерировать фото» фото —
#: объект генерации, а не снимок заказчика.
CUE_REGEX_INPUT = "re!:"

#: Глаголы, которыми ЗАКАЗЫВАЮТ генерацию. Сами по себе операцию не выводят:
#: решает ОБЪЕКТ в той же клаузе (`_по_объекту`).
GENERATE_VERBS: tuple[str, ...] = (
    "сгенерир",
    "генерир",
    "генерац",
    "создать",
    "создай",
    "создайте",
    "нарисова",
    "нарисуй",
    "отрисова",
    "отрендер",
    "generate",
    "create",
    "render",
    "draw",
)

#: Глагол, который и без объекта значит «видео с нуля» — так он работал до
#: 2026-10-14 подсказкой `генерация_видео`, и брифы «сгенерировать с нуля»
#: обязаны собираться как прежде.
GENERATE_VIDEO_BY_DEFAULT: tuple[str, ...] = ("сгенерир",)

#: Объект генерации — КАРТИНКА.
IMAGE_OBJECTS: tuple[str, ...] = (
    "картинк",
    "изображени",
    "кадр",
    "иллюстрац",
    "постер",
    "обложк",
    "re:(?<![а-яё])фото(?![а-яё])",
    "re:(?<![а-яё])фотографи",
    "image",
    "picture",
    "photo",
    "still",
    "keyframe",
    "illustration",
    "poster",
)

#: Объект генерации — ВИДЕО.
VIDEO_OBJECTS: tuple[str, ...] = (
    "видео",
    "ролик",
    "клип",
    "анимац",
    "video",
    "clip",
    "footage",
    "animation",
    # «generated b-roll shots of the product» (2026-10-14, G1): перебивки —
    # видео, и сгенерировать их — генерация видео, а не кадров.
    "b-roll",
    "broll",
    "shots",
)

_КЛАУЗА_ГЕНЕРАЦИИ = re.compile(r"[,;:.!?\n]|\s—\s|\s-\s|\sи\s|\sand\s")


def _слово_есть(слово: str, текст: str) -> bool:
    """Одно слово словаря в тексте: регулярка, латиница по границе, кириллица подстрокой."""
    if слово.startswith(CUE_REGEX):
        return re.search(слово[len(CUE_REGEX) :], текст) is not None
    if _ЛАТИНСКАЯ.match(слово):
        return re.search(rf"\b{re.escape(слово)}", текст) is not None
    return слово in текст


def _клаузы_генерации(низ: str) -> list[str]:
    """Клаузы брифа, в которых стоит НЕОТМЕНЁННЫЙ глагол генерации."""
    клаузы = []
    for клауза in _КЛАУЗА_ГЕНЕРАЦИИ.split(низ):
        глаголы = [г for г in GENERATE_VERBS if _слово_есть(г, клауза)]
        if глаголы and not all(_операция_отменена(клауза, г) for г in глаголы):
            клаузы.append(клауза)
    return клаузы


def _по_объекту(низ: str) -> set[str]:
    """Операции, выведенные парой «глагол генерации + объект» в одной клаузе.

    Заведено 2026-10-14 по живому прогону: подсказка `сгенерир` выводила
    генерацию ВИДЕО из «сгенерировать фотореалистичный ключевой кадр». Объект
    решает, что генерируют: картинку, видео или оба. Без объекта видео выводит
    только прежний глагол (`GENERATE_VIDEO_BY_DEFAULT`) — так бриф «сгенерировать
    с нуля» собирается как раньше.
    """
    найдено: set[str] = set()
    for клауза in _клаузы_генерации(низ):
        картинка = any(_слово_есть(о, клауза) for о in IMAGE_OBJECTS)
        видео = any(_слово_есть(о, клауза) for о in VIDEO_OBJECTS)
        if картинка:
            найдено.add("генерация_изображения")
        if видео or (not картинка and any(г in клауза for г in GENERATE_VIDEO_BY_DEFAULT)):
            найдено.add("генерация_видео")
    return найдено


def _вне_генерации(низ: str) -> str:
    """Бриф, в котором клаузы с глаголом генерации затёрты пробелами.

    Места слов не съезжают — по ним ищутся отмены рядом с подсказкой.
    """
    итог = низ
    for клауза in _клаузы_генерации(низ):
        место = итог.find(клауза)
        if место >= 0:
            итог = итог[:место] + " " * len(клауза) + итог[место + len(клауза) :]
    return итог


def _подсказка_сработала(cue: str, низ: str, без_имён: str, вне_генерации: str) -> bool:
    """Подсказка любой формы: регулярка, регулярка-вход или прежняя."""
    if cue.startswith(CUE_REGEX_INPUT):
        return re.search(cue[len(CUE_REGEX_INPUT) :], вне_генерации) is not None
    if cue.startswith(CUE_REGEX):
        return re.search(cue[len(CUE_REGEX) :], низ) is not None
    return _подсказка_есть(cue, низ, без_имён)


def _заслон_сработал(нет: str, низ: str) -> bool:
    """Слово из `кроме`: регулярка или подстрока."""
    if нет.startswith(CUE_REGEX):
        return re.search(нет[len(CUE_REGEX) :], низ) is not None
    return нет in низ


#: Обороты, при которых голос звучит ЗА КАДРОМ: озвучка и оживлённое лицо
#: тогда не соединяются липсинком. Остальное «оживить + озвучить» — говорящее
#: фото, и без липсинка губы стоят, а голос звучит (живой прогон 2026-10-14:
#: «оживить фото и озвучить по-английски» -> [озвучка, оживление], губы
#: никто не двигал).
OFFSCREEN_VOICE: tuple[str, ...] = (
    "закадров",
    "за кадром",
    "диктор",
    "voice over",
    "voice-over",
    "voiceover",
    "narrat",
    "без липсинк",
    "без синхрон",
)


def derive(brief: str) -> list[Operation]:
    """Какие операции выводятся из брифа. Ни одной — честный ответ.

    Вынесено отдельной функцией из точки входа (Т5): это самая мутирующая
    развилка модуля, и она обязана быть достижима тестом без сборки плана,
    без базы фактов и без валидатора.

    Порядок возвращаемого — порядок `OPERATIONS`, а не порядок слов в брифе:
    план обязан идти от производителей артефактов к их потребителям, а
    заказчик перечисляет как придётся («сделай липсинк под мою озвучку»).
    """
    низ = _norm(brief)
    if not низ:
        return []
    без_имён = _без_имён_собственных(brief)
    вне = _вне_генерации(низ)
    по_объекту = _по_объекту(низ)
    выведены = [
        op
        for op in OPERATIONS
        if (
            any(
                _подсказка_сработала(cue, низ, без_имён, вне) and not _операция_отменена(низ, cue)
                for cue in op.cues
            )
            or op.name in по_объекту
        )
        and not any(_заслон_сработал(нет, низ) for нет in op.кроме)
    ]
    return _апскейл_по_плану(_фото_без_движения(выведены, низ, без_имён, вне), низ)


def _фото_без_движения(
    выведены: list[Operation], низ: str, без_имён: str, вне: str
) -> list[Operation]:
    """Снимок назван, а двигать его никто не просил — оживления нет.

    Подсказки-ВХОДЫ (`CUE_REGEX_INPUT`: фото, портрет) говорят, что снимок
    ЕСТЬ, а не что его оживляют. Пока в брифе нет ни слова о движении, видео
    или речи, а со снимком делают другую работу (апскейл, правку), оживление
    было бы лишним оплачиваемым шагом: «апскейл фото до 4K» не просит видео.
    """
    имена = {оп.name for оп in выведены}
    if "оживление" not in имена or not ({"апскейл", "редактирование_изображения"} & имена):
        return выведены
    оживление = next(оп for оп in выведены if оп.name == "оживление")
    сильные = [c for c in оживление.cues if not c.startswith(CUE_REGEX_INPUT)]
    if any(_подсказка_сработала(c, низ, без_имён, вне) for c in сильные):
        return выведены
    if any(_слово_есть(о, низ) for о in VIDEO_OBJECTS) or ({"липсинк", "озвучка"} & имена):
        return выведены
    return [оп for оп in выведены if оп.name != "оживление"]


#: Операции, после которых в плане есть ВИДЕО, а значит апскейл — видео.
#: `видео_со_звуком` встал сюда 2026-10-15 (валидатор раунда 4): после
#: замены цепочки нативным звуком в плане не оставалось ни одного «видео-
#: делателя», и условный апскейл выбирал апскейлер КАРТИНКИ поверх ролика.
VIDEO_MAKERS: frozenset[str] = frozenset(
    {"оживление", "генерация_видео", "липсинк", "замена_персонажа", "дубляж", AVATAR_STEP, NATIVE_AUDIO_STEP}
)


def _апскейл_по_плану(выведены: list[Operation], низ: str = "") -> list[Operation]:
    """АПСКЕЙЛ БЕЗ ВИДЕО — апскейл кадра: в плане только картинки, и поднимать
    разрешение надо у них (`апскейл_изображения` вместо `апскейл`).

    Видео, НАЗВАННОЕ в брифе, — тоже видео (2026-10-14, G1): «upscale my video
    to 4k» уходило в апскейл КАРТИНКИ и дописывало генерацию кадра, хотя
    поднимать просили разрешение готового ролика.
    """
    имена = {оп.name for оп in выведены}
    if "апскейл" not in имена or VIDEO_MAKERS & имена:
        return выведены
    if низ and any(_слово_есть(о, низ) for о in VIDEO_OBJECTS):
        return выведены
    по_имени = {оп.name: оп for оп in OPERATIONS}
    имена = (имена - {"апскейл"}) | {"апскейл_изображения"}
    return [по_имени[и] for и in (оп.name for оп in OPERATIONS) if и in имена]


def говорящее_фото(операции: Sequence[Operation], brief: str) -> bool:
    """ОЖИВИТЬ + ОЗВУЧИТЬ — говорящее фото: голос и губы соединяет липсинк.

    Если голос заказан ЗА КАДРОМ (`OFFSCREEN_VOICE`), связки нет: диктор
    звучит поверх картинки, и губы двигать некому.
    """
    имена = {оп.name for оп in операции}
    return (
        {"оживление", "озвучка"} <= имена
        and "липсинк" not in имена
        and not any(с in _norm(brief) for с in OFFSCREEN_VOICE)
    )


#: Кем закрывается нехватка артефакта. КОНСТАНТА-РЕШЕНИЕ, ВЫБРАНО 2026-09-03
#: и названо вслух, потому что производителей у артефакта несколько, а
#: подставляем мы ОДНОГО:
#:
#:   аудио -> `озвучка`. Липсинку нужна РЕЧЬ; `звук_фон` даёт шумы, под
#:            которые губы не двигаются, а `дубляж` требует исходной речи,
#:            которой у «с нуля» нет.
#:   видео -> `генерация_видео`. `оживление` требует фотографии, `замена
#:            персонажа` — готового ролика; у того, кто пришёл без исходников,
#:            нет ни того, ни другого.
#:
#: Обе подстановки — догадка о намерении, и поэтому шаг, добавленный так,
#: ПОМЕЧАЕТСЯ в плане (`inferred`). Продукт, который дописывает шаги молча,
#: врёт ровно в ту сторону, от которой его тут и лечили.
ЗАКРЫВАЕТ_НЕХВАТКУ: dict[str, str] = {
    ARTEFACT_AUDIO: "озвучка",
    ARTEFACT_VIDEO: "генерация_видео",
    # Кадр, которого никто не принёс, делает генерация картинки (2026-10-14):
    # оживлять несуществующее селфи — тот самый живой дефект.
    ARTEFACT_IMAGE: "генерация_изображения",
}

#: Видео, которого не хватает, при КАДРЕ в плане делает оживление кадра, а не
#: генерация с нуля: кадры для того и заказывали (ключевые кадры,
#: консистентные персонажи), чтобы видео шло из них. Без кадра — с нуля.
ВИДЕО_ИЗ_КАДРА = "оживление"

#: Пометка липсинка, дописанного к дубляжу готового видео.
DUB_LIPSYNC_NOTE = (
    "дубляж меняет речь готового видео — губы под новый язык двигает липсинк "
    "(лиц в кадре нет — шаг снимается, хватит сведения звука)"
)

#: Пометка дописанного липсинка в говорящем фото.
LINKED_LIPSYNC_NOTE = "голос и оживлённое лицо в брифе не соединены — губы двигает липсинк"


def _кто_закроет(артефакт: str, кадр_есть: bool) -> str:
    """Какая операция закрывает нехватку артефакта. Видео при кадре — из кадра."""
    if артефакт == ARTEFACT_VIDEO and кадр_есть:
        return ВИДЕО_ИЗ_КАДРА
    return ЗАКРЫВАЕТ_НЕХВАТКУ[артефакт]


def замкнуть(
    операции: list[Operation], есть: frozenset[str], brief: str = ""
) -> tuple[list[Operation], dict[str, str]]:
    """Дописать производителей артефактов, которых шагам не хватает.

    ЗАЧЕМ. Заказчик называет операции не все. «Ведущий зачитывает сводку» —
    это липсинк, но ни озвучки, ни генерации видео человек не назвал, потому
    что для него это одна работа. ИЗМЕРЕНО 2026-09-03: из десяти брифов,
    сформулированных РЕЗУЛЬТАТОМ, полный набор шагов выводился у трёх.

    Что считается нехваткой: артефакт, который шаг ТРЕБУЕТ, которого нет у
    заказчика на входе и которого не производит ни один шаг плана.

    Возвращает порядок `OPERATIONS` (план идёт от производителей к
    потребителям) и словарь `имя операции -> из-за какого артефакта добавлена`.
    """
    имена = {оп.name for оп in операции}
    добавлены: dict[str, str] = {}
    по_имени = {оп.name: оп for оп in OPERATIONS}
    if brief and говорящее_фото(операции, brief):
        имена.add("липсинк")
        добавлены["липсинк"] = LINKED_LIPSYNC_NOTE
    # ДУБЛЯЖ ГОТОВОГО ВИДЕО — ЭТО ЕЩЁ И ГУБЫ (2026-10-14, G1). «Перевести готовое
    # видео на испанский»: новая речь в старом кадре без липсинка — это
    # закадровый перевод, а заказали перевод ролика. Шаг помечается, и его
    # можно снять, если лиц в кадре нет.
    if (
        brief
        and "дубляж" in имена
        and ARTEFACT_VIDEO in есть
        and "липсинк" not in имена
        and not any(с in _norm(brief) for с in OFFSCREEN_VOICE)
    ):
        имена.add("липсинк")
        добавлены["липсинк"] = DUB_LIPSYNC_NOTE
    # РОЛИК ЗАКАЗАН, А ВИДЕО НЕ ДЕЛАЕТ НИ ОДИН ШАГ (2026-10-14, G1). «45-second
    # product demo video …, voiceover, music» давало план [озвучка, музыка] и
    # «цену ролика» за одну музыку. Нехватка видео — такая же нехватка, как у
    # липсинка без видео: закрывается генерацией (или оживлением кадра), шаг
    # помечается, а вопрос «видео уже снято?» остаётся — это наша догадка.
    if (
        brief
        and имена
        and ARTEFACT_VIDEO not in есть
        and ролик_заказан(brief)
        # «ключевые кадры для MMA ролика»: ролик — НАЗНАЧЕНИЕ кадров, а не заказ
        # (тот же признак, по которому `clarify` не спрашивает о видео).
        # «30 s instrumental music for an ad», «музыка для рекламы» — то же
        # самое для ДОРОЖКИ (2026-10-15, аудит третьего круга): ролик — её
        # назначение, и шаг генерации видео к музыке не дописывается.
        and not (
            any(
                OUTPUT_KINDS.get(а) in ("изображение", "аудио")
                for имя in имена
                for а in по_имени[имя].produces
            )
            and clarify.ДЛЯ_РОЛИКА.search(_norm(brief))
        )
        and not any(OUTPUT_KINDS.get(а) == "видео" for имя in имена for а in по_имени[имя].produces)
    ):
        кадр_есть = ARTEFACT_IMAGE in есть or any(
            ARTEFACT_IMAGE in по_имени[имя].produces for имя in имена
        )
        имя_видео = _кто_закроет(ARTEFACT_VIDEO, кадр_есть)
        имена.add(имя_видео)
        добавлены[имя_видео] = ARTEFACT_VIDEO

    # Цикл конечен: на каждом обороте добавляется имя из `ЗАКРЫВАЕТ_НЕХВАТКУ`,
    # и повторно оно уже не добавится. Верхняя граница — размер словаря.
    for _ in range(len(ЗАКРЫВАЕТ_НЕХВАТКУ) + 1):
        производится = {а for имя in имена for а in по_имени[имя].produces}
        кадр_есть = ARTEFACT_IMAGE in производится or ARTEFACT_IMAGE in есть
        # Требование закрывает ДРУГОЙ шаг: правка кадра производит кадр, но
        # закрыть собственный вход сама не может (живой прогон 2026-10-14 —
        # «консистентные персонажи» оставались без исходного кадра).
        нехватка = [
            а
            for имя in sorted(имена)
            for а in по_имени[имя].requires
            if а not in есть
            and а not in {п for другое in имена if другое != имя for п in по_имени[другое].produces}
            and а in ЗАКРЫВАЕТ_НЕХВАТКУ
        ]
        новые = {_кто_закроет(а, кадр_есть): а for а in нехватка}.keys() - имена
        if not новые:
            break
        for имя in новые:
            артефакт = next(а for а in нехватка if _кто_закроет(а, кадр_есть) == имя)
            добавлены[имя] = артефакт
            имена.add(имя)

    имена = _аватар_вместо(имена, есть, добавлены)
    return [оп for оп in OPERATIONS if оп.name in имена], добавлены


#: Пометка шага говорящего аватара, заменившего оживление и липсинк.
AVATAR_NOTE = (
    "снимок принесён, и он должен заговорить: одна модель «снимок + голос -> говорящее "
    "видео» вместо оживления и липсинка"
)


def _аватар_вместо(имена: set[str], есть: frozenset[str], добавлены: dict[str, str]) -> set[str]:
    """ОЖИВЛЕНИЕ + ЛИПСИНК НА ПРИНЕСЁННОМ СНИМКЕ -> ГОВОРЯЩИЙ АВАТАР (G3).

    Только когда снимок принёс заказчик: кадр, который план сам генерирует,
    обычно идёт в сцену с движением, и там оживление + липсинк честнее.
    """
    if not ({"оживление", "липсинк"} <= имена and ARTEFACT_IMAGE in есть):
        return имена
    for имя in ("оживление", "липсинк"):
        добавлены.pop(имя, None)
    добавлены[AVATAR_STEP] = AVATAR_NOTE
    return (имена - {"оживление", "липсинк"}) | {AVATAR_STEP}


def вопрос_по_плану(
    brief: str,
    операции: Sequence[Operation],
    есть: Iterable[str],
    дописаны: Mapping[str, str] | None = None,
) -> clarify.Вопрос | None:
    """Один вопрос заказчику по УЖЕ СОБРАННОМУ плану — или None.

    Развилка вынесена из точки входа (Т5) и вызывается ПОСЛЕ `замкнуть`:
    дописанный шаг закрывает нехватку сам, и спрашивать о ней второй раз
    значило бы переспрашивать решённое.

    Имена артефактов передаются в `clarify` параметрами: словарь артефактов
    живёт здесь, и второй его копии там не заводится (Е1).
    """
    return clarify.спросить(
        brief,
        sorted({а for оп in операции for а in оп.produces}),
        sorted(есть),
        артефакт_видео=ARTEFACT_VIDEO,
        артефакт_аудио=ARTEFACT_AUDIO,
        # Артефакты, которые появились ТОЛЬКО из дописанных шагов, то есть из
        # нашей догадки, а не из слов заказчика.
        дописано=sorted(set((дописаны or {}).values())),
        артефакт_кадр=ARTEFACT_IMAGE,
        назначение_не_видео=_АРТЕФАКТЫ_ВИДА("аудио"),
        артефакты_видео=_АРТЕФАКТЫ_ВИДА("видео"),
    )


def _АРТЕФАКТЫ_ВИДА(вид: str) -> tuple[str, ...]:
    """Все артефакты, чей выход — этого вида (`OUTPUT_KINDS`), в порядке словаря."""
    return tuple(а for а, в in OUTPUT_KINDS.items() if в == вид)


